W += c[8]*34.014000; // H2O2
W += c[9]*12.011000; // C
W += c[10]*28.010000; // CO
W += c[11]*44.009000; // CO2
W += c[12]*48.041000; // CH3O2H
W += c[13]*13.019000; // CH
W += c[14]*29.018000; // HCO
W += c[15]*45.017000; // HOCO
W += c[16]*61.016000; // O2CHO
W += c[17]*13.019000; // CHV
W += c[18]*30.026000; // CH2O
W += c[19]*45.017000; // OCHO
W += c[20]*62.024000; // HO2CHO
W += c[21]*14.027000; // CH2
W += c[22]*30.026000; // HCOH
