W += c[35]*47.033000; // HOCH2O
W += c[36]*17.007000; // OHV
W += c[37]*39.950000; // AR
W += c[38]*4.002602; // HE

for (int id = 0; id < 39; ++id) {
sumC += c[id];
}
P = rho * 8.31446261815324e+07 * T * sumC / W; // P = rho*R*T/W

